#include "harness.h"
#include <string.h>
#include "../src/crypto/nacl.h"
#include "../src/disco/disco.h"

/* Upstream's own ping and pong packets and the bytes ours must match:
 * generated by tools/disco-vectors from tailscale.com@9476be9. */
#include "disco_vectors.inc"

static const uint8_t MAGIC[6] = { 0x54, 0x53, 0xf0, 0x9f, 0x92, 0xac };

/* A packet from A carrying an arbitrary plaintext, sealed under DV_SHARED. */
static size_t craft(uint8_t *out, const uint8_t *plain, size_t plen)
{
    memcpy(out, MAGIC, 6);
    memcpy(out + 6, DV_A_PUB, 32);
    memcpy(out + 38, DV_NONCE, 24);
    ts_secretbox_seal(out + 62, DV_SHARED, DV_NONCE, plain, plen);
    return 62 + 16 + plen;
}

static int all_zero(const uint8_t *p, size_t n)
{
    size_t i;
    for (i = 0; i < n; i++)
        if (p[i]) return 0;
    return 1;
}

static void test_shared_and_header(void)
{
    ts_disco_shared s;
    uint8_t p[62];

    ts_disco_shared_init(&s, DV_B_PRIV, DV_A_PUB);
    t_true("disco shared = upstream box.Precompute", memcmp(s.k, DV_SHARED, 32) == 0);
    ts_disco_shared_init(&s, DV_A_PRIV, DV_B_PUB);
    t_true("disco shared symmetric", memcmp(s.k, DV_SHARED, 32) == 0);

    t_true("disco looks_like upstream ping", ts_disco_looks_like(DV_UP_PING, sizeof DV_UP_PING));
    t_true("disco looks_like upstream pong", ts_disco_looks_like(DV_UP_PONG, sizeof DV_UP_PONG));
    t_true("disco looks_like 62 bytes", ts_disco_looks_like(DV_UP_PING, 62));
    t_true("disco looks_like 61 bytes no", !ts_disco_looks_like(DV_UP_PING, 61));
    t_true("disco looks_like empty no", !ts_disco_looks_like(DV_UP_PING, 0));
    memcpy(p, DV_UP_PING, 62);
    p[5] ^= 1;
    t_true("disco looks_like bad magic no", !ts_disco_looks_like(p, 62));
    p[5] ^= 1;
    p[0] = 0x01;   /* a WireGuard handshake initiation */
    t_true("disco looks_like wireguard no", !ts_disco_looks_like(p, 62));
    t_true("disco sender", memcmp(ts_disco_sender(DV_UP_PING), DV_A_PUB, 32) == 0);
}

static void test_open_upstream(void)
{
    ts_disco_shared s;
    ts_disco_msg m;
    uint8_t v4[16];

    ts_disco_shared_init(&s, DV_B_PRIV, DV_A_PUB);

    t_true("disco open upstream ping", ts_disco_open(&m, DV_UP_PING, sizeof DV_UP_PING, &s) == 0);
    t_true("disco upstream ping type", m.type == TS_DISCO_PING);
    t_true("disco upstream ping txid", memcmp(m.txid, DV_UP_TXID, 12) == 0);
    t_true("disco upstream ping has node key", m.have_node_key == 1);
    t_true("disco upstream ping node key", memcmp(m.node_key, DV_A_NODE, 32) == 0);

    t_true("disco open upstream padded ping", ts_disco_open(&m, DV_UP_PING_PAD, sizeof DV_UP_PING_PAD, &s) == 0);
    t_true("disco padded ping fields", m.type == TS_DISCO_PING && m.have_node_key &&
           memcmp(m.txid, DV_UP_TXID, 12) == 0 && memcmp(m.node_key, DV_A_NODE, 32) == 0);

    t_true("disco open upstream keyless ping", ts_disco_open(&m, DV_UP_PING_NOKEY, sizeof DV_UP_PING_NOKEY, &s) == 0);
    t_true("disco keyless ping fields", m.type == TS_DISCO_PING && !m.have_node_key &&
           all_zero(m.node_key, 32) && memcmp(m.txid, DV_UP_TXID, 12) == 0);

    t_true("disco open upstream pong", ts_disco_open(&m, DV_UP_PONG, sizeof DV_UP_PONG, &s) == 0);
    memset(v4, 0, 10);
    v4[10] = v4[11] = 0xff;
    v4[12] = 127; v4[13] = 3; v4[14] = 3; v4[15] = 40;
    t_true("disco upstream pong type", m.type == TS_DISCO_PONG);
    t_true("disco upstream pong txid", memcmp(m.txid, DV_UP_TXID, 12) == 0);
    t_true("disco upstream pong src ::ffff:127.3.3.40", memcmp(m.src_ip16, v4, 16) == 0);
    t_true("disco upstream pong port", m.src_port == DV_DERP_SRC_PORT);
    t_true("disco pong has no node key", !m.have_node_key && all_zero(m.node_key, 32));

    t_true("disco open upstream v6 pong", ts_disco_open(&m, DV_UP_PONG6, sizeof DV_UP_PONG6, &s) == 0);
    t_true("disco v6 pong fields", m.type == TS_DISCO_PONG && memcmp(m.src_ip16, DV_V6_SRC_IP, 16) == 0 &&
           m.src_port == DV_V6_SRC_PORT);
}

static void test_seal(void)
{
    ts_disco_shared s, peer;
    ts_disco_msg m;
    uint8_t out[TS_DISCO_MAX], plain[64], v4[16];
    int n;

    ts_disco_shared_init(&s, DV_B_PRIV, DV_A_PUB);
    ts_disco_shared_init(&peer, DV_A_PRIV, DV_B_PUB);

    n = ts_disco_seal_ping(out, sizeof out, DV_B_PUB, &s, DV_NONCE, DV_OUR_TXID, DV_B_NODE);
    t_true("disco seal ping length", n == TS_DISCO_PING_LEN && n == (int)sizeof DV_OUR_PING);
    t_true("disco seal ping = upstream layout", memcmp(out, DV_OUR_PING, sizeof DV_OUR_PING) == 0);
    t_true("disco our ping plaintext",
           ts_secretbox_open(plain, DV_SHARED, out + 38, out + 62, (size_t)n - 62) == 0 &&
           (size_t)n - 78 == sizeof DV_OUR_PING_PLAIN &&
           memcmp(plain, DV_OUR_PING_PLAIN, sizeof DV_OUR_PING_PLAIN) == 0);
    t_true("disco our ping round trip", ts_disco_open(&m, out, (size_t)n, &peer) == 0 &&
           m.type == TS_DISCO_PING && m.have_node_key && memcmp(m.txid, DV_OUR_TXID, 12) == 0 &&
           memcmp(m.node_key, DV_B_NODE, 32) == 0);

    memset(v4, 0, 10);
    v4[10] = v4[11] = 0xff;
    v4[12] = 127; v4[13] = 3; v4[14] = 3; v4[15] = 40;
    n = ts_disco_seal_pong(out, sizeof out, DV_B_PUB, &s, DV_NONCE, DV_OUR_TXID, v4, DV_DERP_SRC_PORT);
    t_true("disco seal pong length", n == TS_DISCO_PONG_LEN && n == (int)sizeof DV_OUR_PONG);
    t_true("disco seal pong = upstream layout", memcmp(out, DV_OUR_PONG, sizeof DV_OUR_PONG) == 0);
    t_true("disco our pong plaintext",
           ts_secretbox_open(plain, DV_SHARED, out + 38, out + 62, (size_t)n - 62) == 0 &&
           (size_t)n - 78 == sizeof DV_OUR_PONG_PLAIN &&
           memcmp(plain, DV_OUR_PONG_PLAIN, sizeof DV_OUR_PONG_PLAIN) == 0);
    t_true("disco our pong round trip", ts_disco_open(&m, out, (size_t)n, &peer) == 0 &&
           m.type == TS_DISCO_PONG && memcmp(m.txid, DV_OUR_TXID, 12) == 0 &&
           memcmp(m.src_ip16, v4, 16) == 0 && m.src_port == DV_DERP_SRC_PORT);

    memset(out, 0x77, sizeof out);
    t_true("disco seal ping short cap", ts_disco_seal_ping(out, TS_DISCO_PING_LEN - 1, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, DV_B_NODE) == -1);
    t_true("disco seal pong short cap", ts_disco_seal_pong(out, TS_DISCO_PONG_LEN - 1, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, v4, 7) == -1);
    t_true("disco seal short cap writes nothing", out[0] == 0x77 && out[TS_DISCO_PING_LEN - 2] == 0x77);
    t_true("disco seal ping exact cap", ts_disco_seal_ping(out, TS_DISCO_PING_LEN, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, DV_B_NODE) == TS_DISCO_PING_LEN);
    t_true("disco seal pong exact cap", ts_disco_seal_pong(out, TS_DISCO_PONG_LEN, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, v4, 7) == TS_DISCO_PONG_LEN);
}

static void test_reject(void)
{
    static uint8_t p[TS_DISCO_MAX + 64], plain[TS_DISCO_MAX];
    ts_disco_shared s, other;
    ts_disco_msg m;
    size_t n, i;

    ts_disco_shared_init(&s, DV_B_PRIV, DV_A_PUB);

    /* Tampered bytes anywhere in nonce, tag or ciphertext. */
    {
        static const size_t at[] = { 38, 61, 62, 77, 78, 100, 123 };
        for (i = 0; i < sizeof at / sizeof at[0]; i++) {
            memcpy(p, DV_UP_PING, sizeof DV_UP_PING);
            p[at[i]] ^= 0x20;
            t_true("disco tampered byte", ts_disco_open(&m, p, sizeof DV_UP_PING, &s) == -1);
        }
        memcpy(p, DV_UP_PING, sizeof DV_UP_PING);
        p[2] ^= 1;
        t_true("disco bad magic", ts_disco_open(&m, p, sizeof DV_UP_PING, &s) == -1);
    }

    /* Short packets: below header + nonce + tag + type + version. */
    for (n = 0; n < 80; n++)
        if (ts_disco_open(&m, DV_UP_PING, n, &s) != -1) break;
    t_true("disco short packets", n == 80);
    t_true("disco truncated ping", ts_disco_open(&m, DV_UP_PING, sizeof DV_UP_PING - 1, &s) == -1);

    /* Wrong key. */
    ts_disco_shared_init(&other, DV_B_PRIV, DV_B_PUB);
    t_true("disco wrong key", ts_disco_open(&m, DV_UP_PING, sizeof DV_UP_PING, &other) == -1);

    /* Version 1 ping and pong. */
    memset(plain, 0, sizeof plain);
    memcpy(plain, DV_OUR_PING_PLAIN, sizeof DV_OUR_PING_PLAIN);
    plain[1] = 1;
    n = craft(p, plain, sizeof DV_OUR_PING_PLAIN);
    t_true("disco ping version 1", ts_disco_open(&m, p, n, &s) == -1);
    memcpy(plain, DV_OUR_PONG_PLAIN, sizeof DV_OUR_PONG_PLAIN);
    plain[1] = 1;
    n = craft(p, plain, sizeof DV_OUR_PONG_PLAIN);
    t_true("disco pong version 1", ts_disco_open(&m, p, n, &s) == -1);

    /* Unknown types: reported by their byte. */
    memset(plain, 0x33, 40);
    plain[0] = 3;
    plain[1] = 0;
    n = craft(p, plain, 40);
    t_true("disco call-me-maybe reported", ts_disco_open(&m, p, n, &s) == 0 && m.type == 3);
    plain[0] = 0x7f;
    n = craft(p, plain, 2);
    t_true("disco unknown type reported", ts_disco_open(&m, p, n, &s) == 0 && m.type == 0x7f);
    plain[0] = 0;
    n = craft(p, plain, 2);
    t_true("disco type 0 reported", ts_disco_open(&m, p, n, &s) == 0 && m.type == 0);
    plain[0] = 9;
    plain[1] = 2;
    n = craft(p, plain, 2);
    t_true("disco unknown type version 2", ts_disco_open(&m, p, n, &s) == -1);

    /* Ping: zero node key is padding; non-zero bytes after a key are padding. */
    memset(plain, 0, sizeof plain);
    plain[0] = 1;
    memcpy(plain + 2, DV_UP_TXID, 12);
    n = craft(p, plain, 2 + 12 + 32 + 10);
    t_true("disco zero node key is padding", ts_disco_open(&m, p, n, &s) == 0 &&
           m.type == TS_DISCO_PING && !m.have_node_key && memcmp(m.txid, DV_UP_TXID, 12) == 0);
    memcpy(plain + 14, DV_A_NODE, 32);
    memset(plain + 46, 0xee, 40);
    n = craft(p, plain, 2 + 12 + 32 + 40);
    t_true("disco non-zero padding after key", ts_disco_open(&m, p, n, &s) == 0 &&
           m.have_node_key && memcmp(m.node_key, DV_A_NODE, 32) == 0);
    n = craft(p, plain, 2 + 12 + 31);
    t_true("disco 31 key bytes is no key", ts_disco_open(&m, p, n, &s) == 0 &&
           m.type == TS_DISCO_PING && !m.have_node_key);
    n = craft(p, plain, 2 + 12);
    t_true("disco bare txid ping", ts_disco_open(&m, p, n, &s) == 0 && !m.have_node_key);
    n = craft(p, plain, 2 + 11);
    t_true("disco ping 11-byte txid", ts_disco_open(&m, p, n, &s) == -1);

    /* Pong: payload of at least 30 bytes; trailing bytes ignored. */
    memcpy(plain, DV_OUR_PONG_PLAIN, sizeof DV_OUR_PONG_PLAIN);
    for (n = 2; n < 32; n++)
        if (ts_disco_open(&m, p, craft(p, plain, n), &s) != -1) break;
    t_true("disco truncated pong (< 30 bytes)", n == 32);
    memset(plain + 32, 0xab, 20);
    t_true("disco pong with trailing bytes", ts_disco_open(&m, p, craft(p, plain, 52), &s) == 0 &&
           m.type == TS_DISCO_PONG && m.src_port == DV_DERP_SRC_PORT);

    /* A pong opened into a struct that held a ping carries no node key. */
    t_true("disco open ping first", ts_disco_open(&m, DV_UP_PING, sizeof DV_UP_PING, &s) == 0 && m.have_node_key);
    t_true("disco then pong", ts_disco_open(&m, DV_UP_PONG, sizeof DV_UP_PONG, &s) == 0 &&
           !m.have_node_key && all_zero(m.node_key, 32));

    /* Size limit: TS_DISCO_MAX accepted, one more refused. */
    memset(plain, 0, sizeof plain);
    memcpy(plain, DV_OUR_PING_PLAIN, sizeof DV_OUR_PING_PLAIN);
    n = craft(p, plain, TS_DISCO_MAX - 78);
    t_true("disco largest packet", n == TS_DISCO_MAX && ts_disco_open(&m, p, n, &s) == 0 && m.have_node_key);
    n = craft(p, plain, TS_DISCO_MAX - 77);
    t_true("disco oversize packet", ts_disco_open(&m, p, n, &s) == -1);
}

static void test_low_order(void)
{
    static const uint8_t zero_pub[32] = { 0 };
    ts_disco_shared s;
    ts_disco_msg m;
    uint8_t out[TS_DISCO_PING_LEN], ip[16], p[TS_DISCO_PING_LEN];

    memset(s.k, 0x5a, 32);
    ts_disco_shared_init(&s, DV_B_PRIV, zero_pub);
    t_true("disco low-order peer key gives zero key", all_zero(s.k, 32));
    memset(ip, 0, sizeof ip);
    t_true("disco seal ping refuses zero key", ts_disco_seal_ping(out, sizeof out, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, DV_B_NODE) == -1);
    t_true("disco seal pong refuses zero key", ts_disco_seal_pong(out, sizeof out, DV_B_PUB, &s,
           DV_NONCE, DV_OUR_TXID, ip, 1) == -1);
    /* A packet that really is sealed under the all-zero key. */
    memcpy(p, DV_UP_PING, 62);
    ts_secretbox_seal(p + 62, s.k, p + 38, DV_OUR_PING_PLAIN, sizeof DV_OUR_PING_PLAIN);
    t_true("disco open refuses zero key", ts_disco_open(&m, p, sizeof p, &s) == -1);
}

void test_disco(void);

void test_disco(void)
{
    test_shared_and_header();
    test_open_upstream();
    test_seal();
    test_reject();
    test_low_order();
}
